        bosses = {
            { en = "Avatar of Hakkar",
              text = "前往犧牲之坑西側即可進入墮落者的聖所，清完沿途小怪並做好開怪準備。哈卡的化身是48級精英，只有隊裏有人接了相關任務、或已完成該任務並持有後續道具時才能召喚——後者可以不用聖甲蟲之蛋直接召喚哈卡萊護血者。不斷擊殺刷新的小怪，直到出現哈卡萊護血者，殺掉並從屍體上拾取血液。團隊通常把這階段設為自由拾取，讓指定的一人統一拾血（哈卡現身之後記得改回來！）。用血液澆熄房間裏的四個火盆之一，如此反覆，直到再次刷出哈卡萊護血者、四個火盆全部熄滅。如果澆熄最後一個火盆前全隊都貼近牆壁站位，可以在開怪前先脫離戰鬥。本體戰鬥相當直白：他會隨機對一名玩家施放導致瘋狂，最好的應對是眩暈或控制該玩家直到其恢復正常；有機會的話也驅散掉暗言術：痛。其餘時間全力輸出，準備迎接勝利！" },
            { en = "Jammal'an the Prophet",
              text = "當6名阿塔萊防衛者全部倒下後，通往預言者迦瑪蘭的道路便已打開。返回副本入口方向，走左手邊即可。他和可悲的奧戈姆同場出現：坦克拉住預言者迦瑪蘭優先集火，注意打斷他的暗影法術，再轉火奧戈姆。" },
            { en = "Ogom the Wretched",
              text = "當6名阿塔萊防衛者全部倒下後，通往預言者迦瑪蘭的道路便已打開。返回副本入口方向，走左手邊即可。他和預言者迦瑪蘭同場出現：先殺迦瑪蘭，再集火預言者迦瑪蘭身邊的奧戈姆。" },
            { en = "Dreamscythe",
              text = "預言者迦瑪蘭倒下後，雙頭龍德拉維沃爾與德姆塞卡爾會在犧牲之坑現身。這兩條龍比較好打：坦克背靠牆把它們拉住，龍頭始終不要朝着團隊，避免全隊喫到正面錐形吐息和擊退技能。" },
            { en = "Weaver",
              text = "預言者迦瑪蘭倒下後，雙頭龍德拉維沃爾與德姆塞卡爾會在犧牲之坑現身。這兩條龍比較好打：坦克背靠牆把它們拉住，龍頭始終不要朝着團隊，避免全隊喫到正面錐形吐息和擊退技能。" },
            { en = "Hazzas",
              text = "擊殺德拉維沃爾與德姆塞卡爾之後，另外兩條龍哈扎斯與摩弗拉斯會在夢想者之穴外的走廊現身。打法與前面兩條完全一致：儘量別一次引到兩條，並清乾淨附近的小怪。這是面對伊蘭尼庫斯的陰影之前的最後兩場硬仗。" },
            { en = "Morphaz",
              text = "擊殺德拉維沃爾與德姆塞卡爾之後，另外兩條龍哈扎斯與摩弗拉斯會在夢想者之穴外的走廊現身。打法與前面兩條完全一致：儘量別一次引到兩條，並清乾淨附近的小怪。這是面對伊蘭尼庫斯的陰影之前的最後兩場硬仗。" },
            { en = "Shade of Eranikus",
              text = "伊蘭尼庫斯的陰影是55級精英，開怪時會把副本里殘留的龍人全部召到他身邊，所以開打前務必把場上龍人清理乾淨。遠程保持出近戰範圍，躲開他的群體眩暈技能戰爭踐踏；當前仇恨最高的目標會中深度沉睡，可以用漸隱術、拯救祝福、佯攻這類降仇恨技能來控制由誰來承受。近戰永遠別站龍頭前面，同樣提防戰爭踐踏。按機制穩步輸出即可，戰鬥時間很長，治療注意控藍！" },
