                "聯盟做暗爐鑰匙任務的起點同樣在燃燒平原一側。",
            },
        },
        trash = {
            { title = "暗鐵矮人據點",
              text = "暗鐵矮人成群駐守且巡邏密集，逐組拉動，恐懼類技能謹慎使用以免帶出連鎖怪。" },
            { title = "熔岩犬與火元素",
              text = "分佈在大廳與熔岩區，會施放火焰系法術，火抗裝能顯著減低壓力。" },
        },
        bosses = {
            { en = "Lord Roccor",
              text = "洛考爾可以說是全本最簡單的boss之一——60級德魯伊都能單刷他，難度可想而知。戰鬥本身毫無要點，唯一需要留意的是地震術會打斷施法。" },
            { en = "High Interrogator Gerstahn",
              text = "審訊官格斯塔恩 &lt;暮光之錘審問者&gt;通常是大家第一次進本遇到的第一位boss。整體不算難，但不處理機制會翻車。擊殺她是拿到監獄區任務所需物品的必要一步。本場最大的難點是她的心靈尖嘯恐懼，一旦被恐懼亂跑很容易帶出旁邊的怪堆：部落薩滿記得插戰慄圖騰，聯盟矮人牧師上防護恐懼結界；戰士坦克可以嘗試狂暴之怒來對抗，但恐懼時機難以預判，更多靠運氣。其他坦克治療組合以及輸出職業，儘量把自己塞進牆角，減輕恐懼的影響。恐懼之外，驅散暗言術：痛、打斷法力燃燒即可。" },
            { en = "Houndmaster Grebmar",
              text = "馴犬者格雷布瑪爾又是一場輕鬆的戰鬥，只要按照他的巡邏路線來安排就不會出問題。他在兩組犬類小怪之間來回巡邏：先殺他巡邏方向反側的那一組，等他走回去再殺另一組，兩組清完就可以單獨開boss了。" },
            { en = "Ring of Law: Gorosh the Dervish",
              text = "修行者高羅什打法就像一個帶着旋風斬效果和致死打擊的戰士。在致死打擊減益的間隙把治療量拉滿，只要治療能撐過他每次致死打擊的週期，這就是一場輕鬆的戰鬥。" },
            { en = "Ring of Law: Grizzle",
              text = "格里茲爾極其簡單，幾乎沒有什麼需要提防的東西，唯一要留意的還是地震術會打斷施法。" },
            { en = "Ring of Law: Eviscerator",
              text = "剜眼者是煩人大於困難的一位。暗影箭雨相當討厭，但不至於滅團。牧師在這裏可以善用防護暗影，額外的暗影抗性會讓這場戰鬥變得毫無壓力。" },
            { en = "Ring of Law: Ok'thor the Breaker",
              text = "破壞者奧科索爾是法律之環裏最難的一位，技能多、變數大。他打法像法師，變形術臉黑的話可能直接滅團。關鍵是及時驅散變形術，並讓儘可能多的團員保持距離站位，把魔爆術的影響降到最低。" },
            { en = "Ring of Law: Anub'shiah",
              text = "阿努希爾的難度僅次於破壞者奧科索爾。語言詛咒和包圍之網都必須第一時間驅散，這兩個纔是真正的難點，其餘機制並不棘手——除了驅散之外不需要什麼特別的策略。" },
            { en = "Ring of Law: Hedrum the Creeper",
              text = "爬行者赫杜姆是一場非常直白的戰鬥，除了清毒和解掉定身效果之外，沒有更多策略可言。" },
            { en = "Pyromancer Loregrain",
              text = "控火師羅格雷恩是刷新在祭壇旁的可選boss，戰鬥極其簡單，不做相關收集時通常直接跳過。他沒什麼戰術可討論，打掉圖騰就行，輕鬆擊殺。" },
            { en = "Warder Stilgiss",
              text = "典獄官斯迪爾基斯與維雷克同時出現。對五人小隊來說這場戰鬥並不難：先集火殺掉典獄官斯迪爾基斯，再轉火維雷克。" },
            { en = "Verek",
              text = "典獄官斯迪爾基斯與維雷克同時出現。對五人小隊來說這場戰鬥並不難：先集火殺掉典獄官斯迪爾基斯，再轉火維雷克。" },
            { en = "Fineous Darkvire",
              text = "弗諾斯·達克維爾 &lt;首席建築師&gt;是完成相關任務後纔會出現的可選boss，因此很多隊伍選擇繞開他——把通往他路上的增援全部清掉實在太折磨人。本體戰鬥很直白：他打人極疼，還帶治療機制，一定要打斷他的治療，治療則要預讀治療跟上傷害節奏。裝備不好的隊伍，務必把沿路的增援全部清掉，避免意外引到怪導致滅團。" },
            { en = "Lord Incendius",
              text = "伊森迪奧斯是可選boss，但大多數隊伍（連做熔岩奔跑的都算）都會順手把他打掉：好殺，而且他就守在鐵匠要用的黑鐵砧旁邊。伊森迪奧斯本身不難，但坦克和全團都要小心別被擊飛下平臺——掉下去除了死一次，沒有別的辦法上來。" },
            { en = "Bael'Gar",
              text = "貝爾加是可選boss，多數隊伍因為他不影響副本推進而直接跳過。他會召喚需要擊殺的增援；坦克要把貝爾加的面朝向拉離團隊，這樣熔岩噴濺就構不成威脅。除了坦克承傷偏高之外，這場戰鬥相當輕鬆。" },
            { en = "General Angerforge",
              text = "安格弗將軍是可選boss，但很多玩家會專門來刷他的掉落。由於增援多，整體偏難，隊伍缺AoE傷害時會更喫力。打法很直接：他像戰士一樣作戰，戰鬥中會呼叫增援，全力打boss、增援一出來就AoE清掉。增援血量很低，很容易殺。" },
            { en = "Golem Lord Argelmach",
              text = "傀儡統帥阿格曼奇是又一個大多數隊伍打幾輪之後就繞開的可選boss，也是本副本最難的戰鬥之一，這正是很多人乾脆不碰他的原因。進這間房的主要理由是他旁邊的圖紙——每個團隊都需要一名能製造這件物品的工程師，做好常來的準備。這場戰鬥難在閃電鏈：隊伍一旦扎堆，傷害就會源源不斷。真正的關鍵是散開站位，不讓閃電鏈在目標之間隨意彈跳，這是本場最主要的減員機制。" },
            { en = "Guzzler",
              text = "黑鐵酒吧裏的一連串小型遭遇在任務攻略中另有詳述，這裏不再展開。法拉克斯是酒吧裏的主要戰鬥對象。酒吧是黑石深淵裏的一間中立酒館，既有中立酒客，也有普拉格和羅克圖斯·暗契 &lt;瑟銀兄弟會&gt;兩位商人。當然，為了做任務或者殺某些boss，你可能需要故意和酒客們幹上一架。" },
            { en = "Phalanx",
              text = "想快速穿過這間房，直接向普拉格買6瓶酒交給羅克諾特下士。向羅克諾特下士上交三次之後他會暴怒，這會引出法拉克斯來阻止他，混戰之中通往副本深處的門會被撞開。法拉克斯的全力一擊打人相當疼，但也用不着長篇大論的戰術。雖然工具提示說可以把酒瓶扔向酒客，但千萬別這麼做——他們會翻臉。繞過酒吧還有另一種辦法，但更麻煩：需要完成任務，讓娜格瑪拉去誘惑洛克諾特。" },
            { en = "Ambassador Flamelash",
              text = "弗萊拉斯大使在某種意義上是一場DPS競速：戰鬥中會不斷刷新衝向boss的小怪，小怪一旦抵達就會給他施加增益。好在這些小怪很容易在半路截殺。所以打法就是別讓小怪碰到boss、別讓他的增益疊到治療加不上的程度。把層數控制住，這就是一場非常輕鬆的戰鬥。" },
            { en = "Panzor the Invincible",
              text = "無敵的潘佐爾是模具鑄造廠裏的稀有boss。由於法術反轉，他對施法職業相當煩人，但除此之外並不算難。平時很少會遇到他；遇到了，最要緊的就是讓施法職業盯好法術反轉，其餘就是一場輕鬆的戰鬥。" },
            { en = "Chest of The Seven",
              text = "這是另一場相當輕鬆的戰鬥：對抗7波矮人英靈的多階段遭遇。每個英靈對應一個職業（例如牧師、術士、盜賊），但沒必要為每個職業單獨準備策略，他們都很好殺。唯一要擔心的是打得太慢——他們按固定時間依次放出，可能你還沒殺完當前目標，下一個就已經出場了。除了快速逐個擊殺之外沒有別的策略，他們只會施放本體職業的一兩個弱化版技能，儘量別讓自己同時面對兩三個。七位矮人分別是：Hate'rel、Anger'rel、Vile'rel、Gloom'rel、Seeth'rel、Doom'rel、Dope'rel。" },
            { en = "Magmus",
              text = "瑪格姆斯是一場考驗走位的戰鬥，因為整間大廳兩側全程都有火焰噴出。他站在長廳的盡頭，廳內有兩排噴火的傀儡，火焰傷害極高，沾上很快就會沒命。坦克要把瑪格姆斯拉到合適的位置，讓側面的火焰不構成威脅。處理好了站位，這場戰鬥本身相當輕鬆——一切的關鍵就是把boss拉對地方。" },
            { en = "Princess Moira Bronzebeard",
              text = "這是BRD的最終首領戰。團隊有兩種選擇：救下鐵爐堡公主茉艾拉·銅須 &lt;鐵爐堡公主&gt;只殺達格蘭·索瑞森大帝，或者兩個都殺。多數隊伍第一次會選擇救鐵爐堡公主茉艾拉·銅須 &lt;鐵爐堡公主&gt;來完成任務，之後每次再來都會把她殺掉，因為她的掉落相當不錯。" },
            { en = "Emperor Dagran Thaurissan",
              text = "毫無疑問，這是整個副本最艱難的一場遭遇戰，做好苦戰的準備。如果你是戰士坦克或戰士輸出，只要站位從容就能站得住腳。如果你們決定救下鐵爐堡公主茉艾拉·銅須 &lt;鐵爐堡公主&gt;，策略就是讓副坦克或能打斷施法的人纏住她——絕不能讓她整場自由施法，因為她在戰鬥中會協助達格蘭·索瑞森大帝，而且她還很脆。達格蘭·索瑞森大帝一死，她就會解除精神控制變為友善。如果你們打算殺掉鐵爐堡公主茉艾拉·銅須 &lt;鐵爐堡公主&gt;，那就先集火她、再解決達格蘭·索瑞森大帝。務必帶好打斷技能：她自身傷害可觀，再疊加達格蘭·索瑞森大帝的輸出，治療會很難扛住。另外拾取鐵爐堡公主茉艾拉·銅須 &lt;鐵爐堡公主&gt;可能出bug，開打前確保全隊都完成了相應的任務鏈。" },
        },
    },
    lower_blackrock_spire = {
        tagline = "黑石塔下層：食人魔與龍人的巢穴，一路殺向維姆薩拉克。",
        tips = {
            "下層不需要鑰匙，但建議順路做晉升印章任務鏈，為進上層做準備。",
            "煙網蛛後房間旁的下層洞窟是水晶之牙等稀有怪的刷新點，路過用 /target 檢查。",
            "哈雷肯死後基茲魯爾立刻接戰，打完哈雷肯抓緊恢復血藍。",
            "烏洛克召喚戰前確認長矛任務物品已插好，戰鬥中每30秒可秒殺一隻食人魔。",
        },
        entrance = {
            H = "從荒蕪之地的卡加斯向西跑進黑石山。黑石塔入口在內部環橋的上層平臺，與黑石深淵入口相對。進入後沿走廊下行即達下層區域，無需鑰匙。",
            A = {
                "從暴風城飛抵燃燒平原的摩根哨崗（或經暮色森林跑圖）。",
                "進入黑石山，沿環橋走到上層平臺的黑石塔入口進入。",
            },
        },
        trash = {
            { title = "龍人哨衛",
              text = "黑石塔龍人成群且會施放吐息，正面錐形傷害高，坦克記得讓它們背對團隊。" },
            { title = "尖石獸人營地",
              text = "獸人堆裏有治療者和施法者，優先擊殺或打斷，逐組拉動防止連鎖。" },
        },
        bosses = {
            { en = "Spirestone Butcher",
              text = "尖石屠夫是一隻57級精英食人魔，作為稀有怪出現在尖石區域，坦克拉住正常擊殺即可。" },
            { en = "Highlord Omokk",
              text = "歐莫克大王是59級精英食人魔，身邊還帶着兩名食人魔隨從。多數隊伍會控制住一個隨從，坦克把歐莫克大王拉離人群、背靠牆站位，以應對他的擊退。和隊伍商量好隨從的處理方式：控制充足就兩個全控、先殺歐莫克大王；或者全程控住一個，先殺另一個再轉火本體。無論哪種，控制技能都是剛需，能讓這場戰鬥輕鬆許多。歐莫克大王本身打人很疼，治療要盯緊坦克血線——他的狂怒能在瞬間打出毀滅性的傷害。" },
            { en = "Spirestone Battle Lord",
              text = "尖石統帥是一隻偶爾刷新在歐莫克大王附近房間的58級精英食人魔，身邊帶着兩名施法者。多數隊伍選擇先集火殺掉施法者，再轉火尖石統帥，想用控制也可以。他是標準的近戰怪，開打前確認坦克拉好仇恨再全力輸出。" },
            { en = "Shadow Hunter Vosh'gajin",
              text = "暗影獵手沃什加斯是59級精英巨魔，身邊跟着兩名燃棘暗影牧師。與歐莫克大王的處理類似：控制住一個怪，把暗影獵手沃什加斯拉離團隊再打，因為她的妖術一次能波及多名隊員。先把兩個燃棘暗影牧師全部殺掉，再集火暗影獵手沃什加斯。隊裏有能驅散職業的話，記得及時驅掉她的血之詛咒。" },
            { en = "War Master Voone",
              text = "指揮官沃恩是59級精英巨魔，身邊沒有護衛，但打人非常疼。在確定坦克建立起足夠仇恨之前不要開怪。坦克要把他拉到牆邊、自己背靠牆站位；如果指揮官沃恩轉火別人，立即停手，等坦克把仇恨拉回去再繼續輸出。" },
            { en = "Bannok Grimaxe",
              text = "班諾克·巨斧 &lt;火印軍團勇士&gt;是下層最搶手的稀有怪之一，因為他有幾率掉落非常實用的配方。他刷新在煙網蛛後房間前的一間、一堆帳篷旁的獸人區域。記得用 /tar Bannok 檢查他有沒有刷新——他在的話，通常正坐在或睡在角落裏。" },
            { en = "Mother Smolderweb",
              text = "煙網蛛後是下層裏59級精英蜘蛛boss。她的結晶是正面錐形的群體眩暈，所以坦克自然要讓她背對團隊。她還會週期性施放母蛛之奶——一種眩暈目標及其附近玩家的毒藥。盯好這兩個技能，就能比較輕鬆地把她打掉。" },
            { en = "Crystal Fang",
              text = "水晶之牙是刷新在巢穴附近區域的稀有怪，路過時留意一下即可。" },
            { en = "Urok Doomhowl",
              text = "烏洛克是60級精英召喚boss。遭遇開始後，在他本人登場之前會先湧出多波精英食人魔。關鍵在於利用插在貢品堆上的長矛：每30秒可以選中一個食人魔點擊長矛，直接秒殺該波中的一隻食人魔，以此控制每波同時面對的數量。別忘了在點長矛之餘配合控制技能，波次積累起來會非常喫緊。大約殺掉10只左右後，烏洛克纔會終於現身。他擁有戰士類的技能，包括破膽咆哮恐懼。開打前確保坦克拉穩仇恨，再放開輸出。" },
            { en = "Quartermaster Zigris",
              text = "軍需官茲格雷斯 &lt;血斧軍團&gt;是下層的一名精英boss，戰鬥本身不復雜，坦克拉住正常擊殺即可。" },
            { en = "Halycon",
              text = "哈雷肯是精英座狼boss，身邊帶着一群座狼幼崽。坦克拉住哈雷肯，團隊先清掉幼狼小怪，再回頭集火哈雷肯。以她的近戰技能撕裂和痛擊來說，擊殺難度不高。但哈雷肯一倒下，立刻抓緊恢復血量和法力，因為奴役者基茲魯爾馬上就會衝進戰場！" },
            { en = "Gizrul the Slavener",
              text = "奴役者基茲魯爾是精英座狼boss，打人很疼，配合技能能打出毀滅性的傷害：致命刺痛會給他自身回血，感染撕咬則是自然系持續傷害。老規矩，坦克先拉住並建立足夠仇恨，再放開輸出。" },
            { en = "Overlord Wyrmthalak",
              text = "維姆薩拉克是下層的最終boss。坦克開怪時背靠牆、讓他面朝遠離團隊的方向建立初始仇恨。戰鬥進行到他血量降至50%時會召喚增援。多數隊伍會選擇控制住增援、以最快速度把維姆薩拉克打掉，之後再回頭清理小怪。" },
