        entrance = {
            H = "從荒蕪之地的卡加斯向西跑進黑石山。黑石塔入口在內部環橋的上層平臺，進入後先穿下層走廊。在黑石塔下層深處由持有晉升印章的隊友開啓通往上層的龍人門。",
            A = {
                "從暴風城飛抵燃燒平原的摩根哨崗（或經暮色森林跑圖）。",
                "進入黑石塔，穿過後層走廊，由持有晉升印章的隊友開門進入上層。",
            },
        },
        trash = {
            { title = "育龍廳龍蛋",
              text = "踩破龍蛋會孵出小龍並可能連鎖引爆，非事件期間一律貼牆繞行。" },
            { title = "黑手大廳守軍",
              text = "將軍房間前有巡邏與駐守怪混合，開boss前把房間清乾淨。" },
        },
        bosses = {
            { en = "Pyroguard Emberseer",
              text = "這個房間的流程很直接：點擊祭壇激怒所有黑手囚禁者，解除對烈焰衛士的束縛，隨後擊殺艾博希爾，打通進入育龍廳的道路。開怪方式是點擊黑石祭壇。囚禁者血量很低，法師和術士AoE清掉就行。對付艾博希爾，坦克要讓他遠離人群站位，避免多人同時被火焰新星打中。除此之外這場戰鬥相當輕鬆，boss很快就會倒下。" },
            { en = "Solakar Flamewreath",
              text = "育龍廳是全本最大的滅團風險點，因為地上佈滿龍蛋。多數隊伍會避開父焰事件，沿西牆繞到俯瞰育龍廳的高臺；也有團隊選擇做這個事件，但難度不小。要開事件，全團貼緊北牆走到盡頭，先清掉一些龍蛋會有幫助——不過龍蛋會很快重刷，不少團隊因此覺得這是徒勞。先把龍人清理乾淨，然後點擊父焰並拾取物品。事件期間會迎來多波怪物：第一波是育龍廳孵育者，它們會砸蛋，必須第一時間擊殺；破殼而出的小龍交給法師和術士處理。第二波是育龍廳守衛，讓坦克拉住、背靠東牆，優先級低於孵育者。幾分鐘後索拉卡登場——這反而是場簡單的戰鬥：坦克把他拉到牆邊，團隊先清完剩餘小龍再集火他，全團保持距離，他有一發能眩暈全團的戰爭踐踏。擊殺後全團繼續貼牆，沿房間邊緣回到高臺，小龍刷新就AoE清掉；貼角走位可以避免一次踩破多個龍蛋。" },
            { en = "Jed Runewatcher",
              text = "與古拉魯克一樣，這場戰鬥相當輕鬆：坦克背靠牆拉住，團隊保持距離輸出，順利擊殺即可。順帶一提，有的隊伍開跑前會先做 /tar Jed Runewatcher，集合頻道里那句“LFM UBRS doing Jed/Rend”就是從這兒來的。" },
            { en = "Goraluk Anvilcrack",
              text = "這個房間的流程很直接：這裏的boss是古拉魯克，可選boss傑德也可能同在場。清完所有小怪後把古拉魯克和（如果在的）傑德殺掉即可；有的隊伍會整間跳過，因為兩個都是可選boss。戰鬥本身是場基礎遭遇：坦克把他拉在牆邊、遠離團隊。" },
            { en = "Gyth",
              text = "完成挑戰波次後，雷德會騎着蓋斯現身。波次由大量獸人和龍人組成，全部清完後南側大門打開，通往熔爐。大約七到八波之後，雷德就會騎着蓋斯出現。對抗蓋斯時，主坦克要把他面朝拉離團隊，防住吐息；血量降到20%時雷德會被從蓋斯背上擊落，團隊應當先殺蓋斯再轉火雷德。雷德一落地，副坦克要立刻接手，把他拉到房間一側；蓋斯死後全團轉火雷德，近戰注意躲好旋風斬和順劈。他打人非常疼，而這個階段團隊法力已經見底，治療能否撐住是擊殺雷德最大的考驗。" },
            { en = "Warchief Rend Blackhand",
              text = "完成挑戰波次後，雷德會騎着蓋斯現身。波次由大量獸人和龍人組成，全部清完後南側大門打開，通往熔爐。對抗蓋斯時主坦克把他面朝拉離團隊防吐息，血量20%時雷德被擊落，團隊先殺蓋斯再轉火雷德。雷德落地後副坦克立刻接手，把他拉到房間一側；蓋斯死後全團轉火雷德，近戰注意躲好旋風斬和順劈。他打人非常疼，而這個階段團隊法力已經見底，治療能否撐住是擊殺雷德最大的考驗。" },
            { en = "The Beast",
              text = "熔爐房間的目標是擊殺比斯巨獸。這場戰鬥有一定難度，難點集中在三個機制上：第一是 無法躲避的衝鋒，衝鋒結束後他會回到當前仇恨最高的目標身上，所以主坦克必須始終穩居仇恨第一；第二是恐懼，團隊應保持最大距離並散開站位來規避；第三是名為烈焰崩裂的火焰新星，附帶火焰傷害與擊退——坦克背靠牆防擊退，其他人儘量退到最大距離，減少喫到的AoE傷害。" },
            { en = "General Drakkisath",
              text = "這是上層黑石塔的最後一個房間，最終boss達基薩斯將軍就駐守於此，房內還有一些巡邏和站位怪。殺掉將軍即完成本副本。最常見的打法是風箏法（有獵人的隊伍基本都用），比另一種方法簡單得多：獵人把將軍拉開，一路風箏回比斯巨獸的房間，然後假死把將軍交還給團隊；與此同時每名坦克各接一個多彩精英衛士並集火殺掉，主坦克再去接手將軍，面朝拉離團隊防住火焰吐息。拋開衛士不論，將軍本體並不難，這就是團隊偏愛這個方法的原因。第二種打法類似但不風箏：在初始位置同時坦克住增援和將軍，目標是儘快AoE劈死多彩精英衛士；術士可以鏈式恐懼一個衛士來減輕治療壓力。低裝備水平下這個方法明顯更難，因為衛士和將軍的疊加輸出很高。衛士清完之後，和風箏法一樣，將軍本體相當輕鬆。" },
            { en = "Darkstone Tablet",
